mapper.select:
SELECT 
  FROM DASH_WKLY_RPT
 WHERE WEEK_YMD = #{weekYmd}
  AND DEPT_CD = #{deptCd}
  AND PART_CD = #{partCd}
  AND REG_EMPNO = #{regEmpno}
 ORDER BY RPT_ID

SELECT COUNT(*)
  FROM DASH_WKLY_RPT
 WHERE WEEK_YMD  = #{weekYmd}
   AND SR_NO     = #{srNo}
   AND REG_EMPNO = #{regEmpno}

mapper.update:
UPDATE DASH_WKLY_RPT
   SET LEADER_CMT = #{comment,jdbcType=VARCHAR},
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{actor}
 WHERE RPT_ID = #{rptId}

mapper.select:
SELECT 
  FROM DASH_WKLY_SUM
 WHERE WEEK_YMD = #{weekYmd}
  AND DEPT_CD = #{deptCd}
  AND PART_CD = #{partCd}
 ORDER BY DEPT_CD, PART_CD, SUM_ID DESC

mapper.update:
UPDATE DASH_WKLY_SUM
   SET SUM_CNTT   = #{sumCntt},
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{actor}
 WHERE SUM_ID = #{sumId}

UPDATE DASH_WKLY_SUM
   SET TEAM_CMT       = #{comment,jdbcType=VARCHAR},
       TEAM_CMT_EMPNO = #{actor},
       UPDATED_AT     = SYSTIMESTAMP,
       UPDATED_BY     = #{actor}
 WHERE SUM_ID = #{sumId}
